// Writes src/openapi.generated.ts from the built package, so no request pays for generation.
// Run: pnpm --filter @loadstate/core openapi:generate
import { writeFileSync } from "node:fs";
import { createOpenApiDocument } from "../dist/index.js";

const text = JSON.stringify(createOpenApiDocument("3.1.2"));
const lines = [
  "// Generated by packages/core/scripts/generate-openapi.mjs. Do not edit by hand:",
  "// run `pnpm --filter @loadstate/core openapi:generate` and review the diff.",
  `export const openApiJson = ${JSON.stringify(text)};`,
  "",
];
const target = new URL("../src/openapi.generated.ts", import.meta.url);
writeFileSync(target, lines.join("\n"));
console.log(
  `Wrote the OpenAPI document (${(text.length / 1024).toFixed(0)} KiB) to ${target.pathname}`,
);
